SELECT account_type, CASE WHEN YEAR(opened_date) < 2024 THEN 'before_2024' WHEN YEAR(opened_date) = 2024 THEN '2024' ELSE 'after_2024' END AS opened_cohort, status, AVG(balance) AS avg_balance, ROUND((100 * SUM(CASE WHEN account_type = 'LOAN' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_loan, COUNT(CASE WHEN account_type = 'LOAN' THEN 1 END) AS loan_count FROM accounts WHERE balance >= 38000 GROUP BY account_type, opened_cohort, status ORDER BY pct_loan DESC
